{"command": "create", "path": "/workspace/backend/internal/auth/auth.go", "file_text": "package auth

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"

	"golang.org/x/crypto/bcrypt"
)

func HashPassword(password string) (string, error) {
	bytes, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	return string(bytes), err
}

func CheckPassword(password, hash string) bool {
	err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
	return err == nil
}

func ConstantTimeCompare(a, b string) bool {
	return subtle.ConstantTimeCompare([]byte(a), []byte(b)) == 1
}

func GenerateToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

func GenerateID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}"}

{"command": "create", "path": "/workspace/backend/internal/middleware/middleware.go", "file_text": "package middleware

import (
	"context"
	"encoding/json"
	"net/http"
	"strings"

	"lab-sample-system/internal/store"
)

type contextKey string

const (
	SessionKey  contextKey = "session"
	UserIDKey   contextKey = "userId"
	RoleKey     contextKey = "role"
)

type Session struct {
	UserID     string
	ActiveRole string
}

func AuthMiddleware(s *store.Store) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			auth := r.Header.Get("Authorization")
			if auth == "" || !strings.HasPrefix(auth, "Bearer ") {
				writeError(w, http.StatusUnauthorized, "unauthorized", "missing or invalid token")
				return
			}
			token := strings.TrimPrefix(auth, "Bearer ")
			userID, activeRole, err := s.GetSession(r.Context(), token)
			if err != nil {
				writeError(w, http.StatusUnauthorized, "unauthorized", "invalid session")
				return
			}
			ctx := context.WithValue(r.Context(), SessionKey, &Session{UserID: userID, ActiveRole: activeRole})
			ctx = context.WithValue(ctx, UserIDKey, userID)
			ctx = context.WithValue(ctx, RoleKey, activeRole)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

func RequireRoles(roles ...string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			role := GetRole(r.Context())
			for _, allowed := range roles {
				if role == allowed {
					next.ServeHTTP(w, r)
					return
				}
			}
			writeError(w, http.StatusForbidden, "forbidden", "role not permitted")
		})
	}
}

func GetUserID(ctx context.Context) string {
	if v, ok := ctx.Value(UserIDKey).(string); ok {
		return v
	}
	return ""
}

func GetRole(ctx context.Context) string {
	if v, ok := ctx.Value(RoleKey).(string); ok {
		return v
	}
	return ""
}

func writeError(w http.ResponseWriter, code int, errCode, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(map[string]string{"error": msg, "code": errCode})
}"}

{"command": "create", "path": "/workspace/backend/internal/handlers/handlers.go", "file_text": "package handlers

import (
	"encoding/json"
	"log"
	"net/http"
	"time"

	"lab-sample-system/internal/auth"
	"lab-sample-system/internal/middleware"
	"lab-sample-system/internal/models"
	"lab-sample-system/internal/service"
	"lab-sample-system/internal/store"

	"github.com/google/uuid"
)

type Handler struct {
	Store   *store.Store
	Service *service.Service
}

func New(s *store.Store, svc *service.Service) *Handler {
	return &Handler{Store: s, Service: svc}
}

func respond(w http.ResponseWriter, code int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(v)
}

func errResp(w http.ResponseWriter, code int, errCode, msg string) {
	respond(w, code, map[string]string{"error": msg, "code": errCode})
}

func getReqBody(r *http.Request, v interface{}) error {
	defer r.Body.Close()
	return json.NewDecoder(r.Body).Decode(v)
}

func (h *Handler) writeAudit(userID, role, action, entityType, entityID string, success bool, details string) {
	e := models.AuditEntry{
		AuditID:    uuid.New().String(),
		ActorID:    userID,
		Role:       role,
		ActorRole:  role,
		Action:     action,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: time.Now().UTC(),
		Details:    details,
	}
	if err := h.Store.WriteAudit(r.Context(), e); err != nil {
		log.Printf("audit write error: %v", err)
	}
}

func addTimeline(sampleID, userID, role, action, details string, success bool, store *store.Store) {
	now := time.Now().UTC()
	te := models.TimelineEntry{
		EventID:    uuid.New().String(),
		Action:     action,
		ActorID:    userID,
		Role:       role,
		EntityType: "sample",
		EntityID:   sampleID,
		Success:    success,
		OccurredAt: now,
		Details:    details,
	}
	store.AddSampleTimeline(context.Background(), te)
}

import "context"

// SystemReadiness
func (h *Handler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
	err := h.Store.DB().PingContext(r.Context())
	if err != nil {
		respond(w, http.StatusServiceUnavailable, map[string]string{"status": "not_ready"})
		return
	}
	if _, err := h.Store.Redis().Ping(r.Context()).Result(); err != nil {
		respond(w, http.StatusServiceUnavailable, map[string]string{"status": "not_ready"})
		return
	}
	respond(w, http.StatusOK, map[string]string{"status": "ready"})
}

// AuthenticateUser
func (h *Handler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}
	if req.Username == "" || req.Password == "" {
		errResp(w, 400, "invalid_json", "username and password required")
		return
	}

	user, err := h.Store.GetUserByUsername(r.Context(), req.Username)
	if err != nil {
		errResp(w, 401, "unauthorized", "invalid credentials")
		return
	}
	if !user.Active {
		errResp(w, 401, "unauthorized", "account deactivated")
		return
	}
	if !auth.CheckPassword(req.Password, user.PasswordHash) {
		errResp(w, 401, "unauthorized", "invalid credentials")
		return
	}

	token, err := auth.GenerateToken()
	if err != nil {
		errResp(w, 500, "internal_error", "failed to create session")
		return
	}

	activeRole := ""
	if len(user.Roles) > 0 {
		activeRole = user.Roles[0]
	}

	if err := h.Store.CreateSession(r.Context(), token, user.ID, activeRole, 24*time.Hour); err != nil {
		errResp(w, 500, "internal_error", "failed to create session")
		return
	}

	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"sessionToken": token,
			"userId":       user.ID,
			"roles":        user.Roles,
			"activeRole":   activeRole,
		},
	})
}

// SelectActiveRole
func (h *Handler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	userID := middleware.GetUserID(r.Context())
	user, err := h.Store.GetUserByID(r.Context(), userID)
	if err != nil {
		errResp(w, 404, "not_found", "user not found")
		return
	}

	valid := false
	for _, rl := range user.Roles {
		if rl == req.Role {
			valid = true
			break
		}
	}
	if !valid {
		errResp(w, 400, "invalid_json", "user does not have that role")
		return
	}

	// Extract token from auth header
	authHdr := r.Header.Get("Authorization")
	token := ""
	if len(authHdr) > 7 && authHdr[:7] == "Bearer " {
		token = authHdr[7:]
	}

	if token != "" {
		h.Store.UpdateSessionRole(r.Context(), token, req.Role)
	}

	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"activeRole": req.Role,
			"roles":      user.Roles,
		},
	})
}

// CreateUser
func (h *Handler) CreateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username           string                 `json:"username"`
		InitialPassword    string                 `json:"initialPassword"`
		Email              string                 `json:"email"`
		FullName           string                 `json:"fullName"`
		Phone              string                 `json:"phone"`
		Roles              []string               `json:"roles"`
		Qualifications     []models.Qualification `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             *bool                  `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	hash, err := auth.HashPassword(req.InitialPassword)
	if err != nil {
		errResp(w, 500, "internal_error", "password hashing failed")
		return
	}

	active := true
	if req.Active != nil {
		active = *req.Active
	}

	user := &models.User{
		ID:                 uuid.New().String(),
		Username:           req.Username,
		PasswordHash:       hash,
		Email:              req.Email,
		FullName:           req.FullName,
		Phone:              req.Phone,
		Roles:              req.Roles,
		Qualifications:     req.Qualifications,
		Certifications:     req.Certifications,
		Active:             active,
		AssignedLocationID: req.AssignedLocationID,
	}

	if err := h.Store.CreateUser(r.Context(), user); err != nil {
		errResp(w, 409, "idempotency_conflict", "username already exists")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "user.created", "user", user.ID, true, "")

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         user.ID,
			"username":       user.Username,
			"email":          user.Email,
			"fullName":       user.FullName,
			"phone":          user.Phone,
			"roles":          user.Roles,
			"qualifications": user.Qualifications,
			"certifications": user.Certifications,
			"active":         user.Active,
		},
	})
}

// ReadUser
func (h *Handler) ReadUser(w http.ResponseWriter, r *http.Request) {
	userID := r.PathValue("userId")
	user, err := h.Store.GetUserByID(r.Context(), userID)
