	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "user.updated", "user", req.UserID, true, "")
	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         req.UserID,
