{"command": "create", "path": "/workspace/frontend/src/api.ts", "file_text": "const BASE = '/api'

function getToken(): string | null {
  return localStorage.getItem('sessionToken')
}

function getHeaders(): Record<string, string> {
  const h: Record<string, string> = { 'Content-Type': 'application/json' }
  const t = getToken()
  if (t) h['Authorization'] = `Bearer ${t}`
  return h
}

export async function api(method: string, path: string, body?: unknown): Promise<{ ok: boolean; status: number; data: any }> {
  const opts: RequestInit = { method, headers: getHeaders() }
  if (body) opts.body = JSON.stringify(body)
  const res = await fetch(`${BASE}${path}`, opts)
  let data: any = null
  try { data = await res.json() } catch {}
  return { ok: res.ok, status: res.status, data }
}

export async function login(username: string, password: string) {
  const r = await api('POST', '/authenticate-user', { username, password })
  if (r.ok && r.data?.data?.sessionToken) {
    localStorage.setItem('sessionToken', r.data.data.sessionToken)
  }
  return r
}

export function logout() {
  localStorage.removeItem('sessionToken')
  window.location.reload()
}

export function getStoredRole(): string | null {
  return localStorage.getItem('activeRole')
}

export function setStoredRole(role: string) {
  localStorage.setItem('activeRole', role)
}"}

{"command": "create", "path": "/workspace/frontend/src/App.tsx", "file_text": "import { useState, useEffect, useCallback } from 'react'
import { api, login, logout, getStoredRole, setStoredRole } from './api'

interface AuthState {
  loggedIn: boolean
  sessionToken: string | null
  userId: string | null
  roles: string[]
  activeRole: string | null
}

function useAuth(): AuthState & { setActiveRole: (r: string) => void; refresh: () => void } {
  const [st, setSt] = useState<AuthState>(() => ({
    loggedIn: !!localStorage.getItem('sessionToken'),
    sessionToken: localStorage.getItem('sessionToken'),
    userId: null,
    roles: [],
    activeRole: getStoredRole(),
  }))
  const refresh = useCallback(async () => {
    const t = localStorage.getItem('sessionToken')
    if (!t) {
      setSt({ loggedIn: false, sessionToken: null, userId: null, roles: [], activeRole: null })
      return
    }
    try {
      const r = await api('GET', `/ui/bootstrap`)
      if (r.ok && r.data?.data) {
        setSt({
          loggedIn: true,
          sessionToken: t,
          userId: r.data.data.userId,
          roles: r.data.data.roles || [],
          activeRole: getStoredRole() || r.data.data.activeRole || r.data.data.roles?.[0] || null,
        })
      } else {
        localStorage.removeItem('sessionToken')
        setSt({ loggedIn: false, sessionToken: null, userId: null, roles: [], activeRole: null })
      }
    } catch {
      setSt({ loggedIn: false, sessionToken: null, userId: null, roles: [], activeRole: null })
    }
  }, [])
  useEffect(() => { if (st.loggedIn) refresh() }, [st.loggedIn, refresh])
  const setActiveRole = (role: string) => {
    setStoredRole(role)
    setSt(s => ({ ...s, activeRole: role }))
    api('POST', '/select-active-role', { role }).catch(() => {})
  }
  return { ...st, setActiveRole, refresh }
}

export default function App() {
  const auth = useAuth()
  if (!auth.loggedIn) return <LoginScreen onLogin={() => auth.refresh()} />
  return <MainLayout auth={auth} />
}

function LoginScreen({ onLogin }: { onLogin: () => void }) {
  const [username, setUser] = useState('')
  const [password, setPass] = useState('')
  const [err, setErr] = useState('')
  const [loading, setLoading] = useState(false)

  const handle = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setErr('')
    const r = await login(username, password)
    if (r.ok) { onLogin() } else { setErr(r.data?.error || 'Login failed') }
    setLoading(false)
  }

  return (
    <div className="login">
      <div className="card">
        <h2>Lab Sample System</h2>
        {err && <div className="error-banner">{err}</div>}
        <form onSubmit={handle}>
          <div className="form-group"><label>Username</label><input value={username} onChange={e => setUser(e.target.value)} required /></div>
          <div className="form-group"><label>Password</label><input type="password" value={password} onChange={e => setPass(e.target.value)} required /></div>
          <button className="btn btn-primary" style={{width:'100%'}} disabled={loading}>{loading ? 'Signing in...' : 'Sign In'}</button>
        </form>
      </div>
    </div>
  )
}

function MainLayout({ auth }: { auth: any }) {
  const [page, setPage] = useState('dashboard')

  const rolePages: Record<string, string[]> = {
    requester: ['dashboard', 'serviceability', 'new-request', 'my-samples'],
    certified_collection_professional: ['dashboard', 'my-work', 'location'],
    relay_courier: ['dashboard', 'my-work', 'location'],
    node_handler: ['dashboard', 'my-work', 'node'],
    laboratory_intake_operator: ['dashboard', 'my-work', 'lab-capacity'],
    dispatcher: ['dashboard', 'monitor', 'audit', 'users', 'locations', 'sample-types', 'connections'],
    administrator: ['dashboard', 'monitor', 'audit', 'users', 'locations', 'sample-types', 'connections'],
  }

  const navPages = auth.activeRole ? rolePages[auth.activeRole] || ['dashboard'] : ['dashboard']

  const renderPage = () => {
    switch (page) {
      case 'serviceability': return <ServiceabilityCheck />
      case 'new-request': return <NewRequest auth={auth} />
      case 'my-samples': return <RequesterSamples auth={auth} />
      case 'my-work': return <MyWork auth={auth} />
      case 'location': return <WorkerLocation auth={auth} />
      case 'node': return <NodeHandler auth={auth} />
      case 'lab-capacity': return <LabIntake auth={auth} />
      case 'monitor': return <MonitorDashboard />
      case 'audit': return <AuditView />
      case 'users': return <UserManagement />
      case 'locations': return <LocationManagement />
      case 'sample-types': return <SampleTypeManagement />
      case 'connections': return <ConnectionManagement />
      case 'dashboard':
      default:
        return <Dashboard auth={auth} />
    }
  }

  return (
    <div className="app">
      <nav className="nav">
        <div className="nav-brand">Lab Sample Pickup & Delivery</div>
        <div className="nav-controls">
          {auth.roles.length > 1 && (
            <select className="nav-select" value={auth.activeRole || ''} onChange={e => { auth.setActiveRole(e.target.value); setPage('dashboard') }}>
              {auth.roles.map((r: string) => <option key={r} value={r}>{r}</option>)}
            </select>
          )}
          {navPages.map(p => (
            <button key={p} className={`nav-btn ${page===p?'btn-primary':''}`} style={page===p?{background:'#0a3d62'}:{}}
                    onClick={() => setPage(p)}>{p.replace(/-/g,' ')}</button>
          ))}
          <button className="nav-btn" onClick={logout}>Sign Out</button>
        </div>
      </nav>
      <div className="container">{renderPage()}</div>
    </div>
  )
}

