{"command": "python3 << 'PYEOF'
import json
with open('/workspace/contracts/openapi.contract.json') as f:
    c = json.load(f)

check_ops = [
    'set_location_status', 'set_location_function_status', 'set_connection_status',
    'configure_capacity', 'configure_laboratory_acceptance', 'create_connection',
    'create_sample_type', 'update_sample_type', 'select_active_role',
    'record_worker_location', 'read_serviceability_snapshot', 'update_location',
    'update_assignment_progress', 'decline_assignment'
]

for path, methods in c['paths'].items():
    for method, details in methods.items():
        op = details.get('operationId', '')
        if op in check_ops:
            print(f"\n=== {op} ===")
            for code in ['200', '201']:
                if code in details['responses']:
                    cr = details['responses'][code].get('content', {}).get('application/json', {}).get('schema', {})
                    if cr:
                        data_prop = cr.get('properties', {}).get('data', {})
                        if data_prop:
                            if '$ref' in data_prop:
                                ref = data_prop['$ref']
                                sname = ref.split('/')[-1]
                                s = c['components']['schemas'].get(sname, {})
                                print(f"  {code}: data $ref={sname}, required={s.get('required', [])}")
                            elif 'properties' in data_prop:
                                req = data_prop.get('required', [])
                                props = list(data_prop['properties'].keys())
                                print(f"  {code}: data props={props}, required={req}")
                            elif 'oneOf' in data_prop:
                                print(f"  {code}: data oneOf")
                            elif 'allOf' in data_prop:
                                print(f"  {code}: data allOf with {data_prop.get('allOf', [])}")
                    break
PYEOF"}
